 // OMEGA-BLOCK-START
 // Computes C = A * B. C is NOT zeroed by the caller. Any number of threads may be
 // used (std::thread is available); n is any size from 1 to 2048.
+#include <algorithm>
+#include <thread>
+#include <vector>
+#include <atomic>
+#if defined(__ARM_NEON)
+#include <arm_neon.h>
+#endif
+
+namespace {
+    // Block sizes for cache tiling.
+    constexpr int MB = 64;  // block size for i dimension
+    constexpr int NB = 64;  // block size for j dimension
+    constexpr int KB = 32;  // block size for k dimension
+
+    // Micro-kernel for a specific tile of C.
+    // Computes C_tile += A_tile * B_tile.
+    // A_tile is [mr x KB], B_tile is [KB x nr], C_tile is [mr x nr].
+    // A_tile rows are contiguous in memory with stride n.
+    // B_tile columns are contiguous in memory with stride n.
+    void matmul_tile(int n, int mr, int nr, int kb,
+                     const float* A_base, const float* B_base, float* C_base) {
+        // A_base points to A[i_start][k_start]
+        // B_base points to B[k_start][j_start]
+        // C_base points to C[i_start][j_start]
+        
+        // Iterate over k in the block
+        for (int k = 0; k < kb; ++k) {
+            // Pointer to A[i][k_start + k]
+            const float* a_ptr = A_base + k; 
+            // Pointer to B[k_start + k][j]
+            const float* b_ptr = B_base + k * n;
+            // Pointer to C[i][j_start]
+            float* c_ptr = C_base;
+
+            // Iterate over i in the block
+            for (int i = 0; i < mr; ++i) {
+                float a_val = *a_ptr;
+#if defined(__ARM_NEON)
+                // Vectorized inner loop for j
+                int j = 0;
+                float32x4_t acc = vdupq_n_f32(0.0f);
+                int limit = nr;
+                for (; j + 3 < limit; j += 4) {
+                    float32x4_t b_vec = vld1q_f32(b_ptr + j);
+                    acc = vfmaq_f32(acc, b_vec, a_val);
+                }
+                vst1q_f32(c_ptr + j, acc);
+                // Scalar tail
+                for (; j < limit; ++j) {
+                    c_ptr[j] += a_val * b_ptr[j];
+                }
+#else
+                // Scalar fallback
+                for (int j = 0; j < nr; ++j) {
+                    c_ptr[j] += a_val * b_ptr[j];
+                }
+#endif
+                a_ptr += n; // Move to next row of A
+                c_ptr += n; // Move to next row of C
+            }
+        }
+    }
+
+    void matmul_threaded(int n, const float* A, const float* B, float* C) {
+        // Clear C
+        std::fill(C, C + (size_t)n * n, 0.0f);
+
+        if (n == 0) return;
+
+        // Use static thread pool logic or simple threads.
+        // For simplicity and robustness in this constrained env, we use std::thread.
+        // To avoid overhead for small n, just do serial if n is small.
+        int num_threads = (n < 64) ? 1 : std::min(10, n / 8); 
+        
+        if (num_threads <= 1) {
+            // Serial execution
+            for (int ir = 0; ir < n; ir += MB) {
+                int mr = std::min(MB, n - ir);
+                for (int jr = 0; jr < n; jr += NB) {
+                    int nr = std::min(NB, n - jr);
+                    for (int kr = 0; kr < n; kr += KB) {
+                        int kb = std::min(KB, n - kr);
+                        matmul_tile(n, mr, nr, kb, 
+                                    A + ir * n + kr, 
+                                    B + kr * n + jr, 
+                                    C + ir * n + jr);
+                    }
+                }
+            }
+            return;
+        }
+
+        std::vector<std::thread> threads;
+        threads.reserve(num_threads);
+
+        for (int t = 0; t < num_threads; ++t) {
+            threads.emplace_back([=, &A, &B, &C]() {
+                // Each thread processes disjoint row blocks
+                for (int ir = t * MB; ir < n; ir += num_threads * MB) {
+                    int mr = std::min(MB, n - ir);
+                    for (int jr = 0; jr < n; jr += NB) {
+                        int nr = std::min(NB, n - jr);
+                        for (int kr = 0; kr < n; kr += KB) {
+                            int kb = std::min(KB, n - kr);
+                            matmul_tile(n, mr, nr, kb,
+                                        A + ir * n + kr,
+                                        B + kr * n + jr,
+                                        C + ir * n + jr);
+                        }
+                    }
+                }
+            });
+        }
+        for (auto& th : threads) {
+            th.join();
+        }
+    }
+}
